const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const n = data[0];
const a = data.slice(1, 1 + n);

a.sort((x, y) => x - y);

let ans = 0;

for (let k = 2; k < n; k++) {
  let i = 0;
  let j = k - 1;
  const target = a[k];

  while (i < j) {
    if (a[i] + a[j] > target) {
      ans += j - i;
      j--;
    } else {
      i++;
    }
  }
}

console.log(ans);
